      const bar = (yy, vals, lab) => { B.text(lab, a.x + 6, yy - 4, { size: 11, w: 700 }); let x = a.x + 80; vals.forEach(([v, col]) => { const w = v * 6; g.save(); g.fillStyle = col; g.fillRect(Math.min(x, x + w), yy - 12, Math.abs(w), 12); g.restore(); x += w; }); B.text("Σ = " + f(vals.reduce((s2, v) => s2 + v[0], 0), 3) + " kg m/s", a.x + a.w - 6, yy - 2, { align: "right", size: 11, w: 700 }); };
